 function reset(){target=P.platform(level);body={x:177,y:350,vx:0,vy:0,angle:0};state='ready';power=0;trail=[];particles=[];bounce=0;settle=0;$('result').hidden=true;$('level').textContent=String(level).padStart(2,'0');$('status').textContent='小伙伴已就位';$('hint').textContent='按住蓄力，松开起飞';$('button-text').textContent='按住蓄力';$('throw').disabled=false;$('bubble').hidden=false;$('bubble').textContent=attempts?'再来！这次一定能上岸。':'目标：对面那块绿色平台！';meter();}
 function meter(){$('power').style.width=power*100+'%';document.querySelector('.meter').setAttribute('aria-valuenow',Math.round(power*100));$('power-label').textContent=state==='charging'?Math.round(power*100)+'% 力度':'准备起飞';}
 function begin(){if(state!=='ready')return;state='charging';chargeStart=performance.now();$('throw').classList.add('charging');$('button-text').textContent='松开起飞';$('hint').textContent='看好力度，松手！';$('bubble').textContent='我准备好了……大概吧。';tone(230);}
 function release(){if(state!=='charging')return;state='flying';Object.assign(body,P.velocity(power));$('throw').classList.remove('charging');$('throw').disabled=true;$('button-text').textContent='飞行中…';$('status').textContent='空中救援进行中';$('bubble').hidden=true;$('hint').textContent='飞吧！落在绿色平台上';tone(480,.18);}
 function cancel(){if(state!=='charging')return;$('throw').classList.remove('charging');reset();}
 function finish(win){state=win?'won':'lost';$('result').hidden=false;$('result-icon').textContent=win?'✦':'≈';$('result-title').textContent=win?'救到了，姿势满分！':'噗通！海水有点咸';$('result-text').textContent=win?'小伙伴安全着陆。下一位已经在排队了。':failReason;$('retry').textContent=win?'下一关，继续救 ↗':'再扔一次 ↗';$('status').textContent=win?'救援成功':'别急，随时再来';$('hint').textContent=win?'漂亮！又救到一位小伙伴':'差一点！调整力度再来';if(win){best=Math.max(best,level);try{localStorage.setItem('rescue-best',String(best));}catch{}$('best').innerHTML=best+' <small>关</small>';tone(660,.2);}else{attempts++;tone(140,.2);}}
 $('throw').addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();$('throw').setPointerCapture(e.pointerId);begin();});$('throw').addEventListener('pointerup',e=>{e.preventDefault();release();});$('throw').addEventListener('pointercancel',cancel);$('throw').addEventListener('contextmenu',e=>e.preventDefault());
 window.addEventListener('keydown',e=>{if(e.code!=='Space'||e.target.tagName==='BUTTON'&&e.target!==$('throw'))return;e.preventDefault();if(e.repeat)return;if(state==='won'||state==='lost'){advance();return;}begin();});window.addEventListener('keyup',e=>{if(e.code==='Space'){e.preventDefault();release();}});window.addEventListener('blur',cancel);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancel();last=0;}});
 function advance(){if(state==='won'){level++;attempts=0;}reset();} $('retry').onclick=advance;$('restart').onclick=()=>{level=1;attempts=0;$('throw').classList.remove('charging');reset();};$('sound').onclick=()=>{sound=!sound;$('sound').textContent='声音：'+(sound?'开':'关');$('sound').setAttribute('aria-pressed',String(sound));tone(440);};
 function shape(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
 function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
