 function platform(p,start){shape(p.x,p.y,p.w,130,12,'#b3bda3');shape(p.x,p.y,p.w,15,6,start?'#73967a':'#6e9c66');shape(p.x+9,p.y+18,p.w-18,7,3,'#d0d4b8');for(let i=0;i<4;i++)line(p.x+18+i*37,p.y+46,p.x+30+i*37,p.y+53,'#9fae94',3);if(!start){line(p.x+p.w-28,p.y,p.x+p.w-28,p.y-85,'#637a5d',3);ctx.fillStyle='#f2bd54';ctx.beginPath();ctx.moveTo(p.x+p.w-28,p.y-85);ctx.lineTo(p.x+p.w+13,p.y-71);ctx.lineTo(p.x+p.w-28,p.y-57);ctx.fill();text('安全区',p.x+p.w/2,p.y+49,17,'#4c6e4e');}}
