(function(root){
  'use strict';
  const gravity=650;
  function velocity(power){return {vx:190+430*power,vy:-(260+230*power)};}
  function step(body,dt){body.vy+=gravity*dt;body.x+=body.vx*dt;body.y+=body.vy*dt;return body;}
  function landing(previous,body,platform){if(body.vy<=0||previous.y>platform.y||body.y<platform.y)return null;const t=(platform.y-previous.y)/(body.y-previous.y);const x=previous.x+(body.x-previous.x)*t;return x>=platform.x+7&&x<=platform.x+platform.w-7?x:null;}
  function platform(level){return {x:575+Math.min(165,(level-1)*13)+Math.sin(level*1.7)*22,y:368-Math.sin(level*.9)*25,w:Math.max(104,190-(level-1)*7)};}
  const api={gravity,velocity,step,landing,platform};root.RescuePhysics=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
